<script setup lang="ts">import {computed,ref} from 'vue';import {useQuery} from '@tanstack/vue-query';import {crmRepository} from '../../services/crmRepository';import EntityTable from '../../components/common/EntityTable.vue';import ProjectProgressPanel from '../../components/project/ProjectProgressPanel.vue';const selected=ref<Record<string,unknown>|null>(null);const query=useQuery({queryKey:['projects','milestones'],queryFn:()=>crmRepository.projects({page:1,pageSize:100})});const rows=computed(()=>query.data.value?.items||[]);</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">PROJECT MANAGEMENT</span><h2>项目管理 · 里程碑计划</h2></div><button class="secondary" @click="query.refetch()">刷新</button></div><p class="muted">项目阶段、里程碑、交付物、风险与变更统一在此查看；暂未接入的接口保留清晰待接入状态。</p><div v-if="query.isPending" class="state">正在加载项目…</div><div v-else-if="query.isError" class="state error">项目加载失败。</div><div v-else-if="!rows.length" class="state">暂无项目。</div><EntityTable v-else :columns="['项目名称','客户','状态','负责人']" :rows="rows" :cell="(item,index)=>[item.name,item.customerName,item.status,item.ownerName][index]||'—'" @select="selected=$event"/><div v-if="selected" class="detail-drawer-inline"><h3>{{selected.name||'项目详情'}}</h3><ProjectProgressPanel :status="String(selected.status||'项目立项')"/><button class="secondary" @click="selected=null">关闭详情</button></div></section></template>
